<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/bootstrap.php';require_role('ADMIN');$error='';$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();$code=text_input($_POST,'code',20);$name=text_input($_POST,'name',120);if(!preg_match('/^[A-Z][A-Z0-9]{1,19}$/D',$code)){throw new ValidationException(['code'=>'Use the uppercase programme code present in registration numbers.']);}unique_reference_value($pdo,'programmes','code',$code,'code');$pdo->prepare('INSERT INTO programmes(code,name) VALUES (?,?)')->execute([$code,$name]);audit($pdo,'PROGRAMME_CREATED',(int)current_user()['id'],null,$code);flash('success','Programme added.');redirect('admin/programmes.php');}catch(Throwable $e){$error=page_error($e,$errors);}}
$rows=$pdo->query('SELECT * FROM programmes ORDER BY code')->fetchAll();$pageTitle='Programmes';require_once __DIR__.'/../includes/header.php';?>
<section class="panel"><h1>Programmes</h1><?php if($error):?><div class="alert danger"><?=e($error)?></div><?php endif;?><form method="post"><?php csrf_field();form_fields(['code'=>['label'=>'Programme code','required'=>true,'maxlength'=>20,'pattern'=>'[A-Z][A-Z0-9]{1,19}'],'name'=>['label'=>'Programme name','required'=>true,'maxlength'=>120]],$errors);?><button class="btn primary" type="submit">Add programme</button></form></section><section class="panel"><div class="table-wrap"><table><thead><tr><th>Code</th><th>Name</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><?=e($row['code'])?></td><td><?=e($row['name'])?></td><td><?=$row['active']?'Active':'Inactive'?></td></tr><?php endforeach;?></tbody></table></div></section><?php require_once __DIR__.'/../includes/footer.php';?>
